-- Mode mythique M0 à M+10 (généré)
SET NAMES utf8mb4;
DELETE FROM creature WHERE id BETWEEN 990113 AND 990124;
DELETE FROM creature_template WHERE Entry BETWEEN 990113 AND 990124;
DELETE FROM gossip_menu WHERE entry=60101;
DELETE FROM npc_text WHERE ID=990101;
DELETE FROM item_template WHERE entry BETWEEN 996000 AND 996999;
DELETE FROM reference_loot_template WHERE entry BETWEEN 996000 AND 996099;
DELETE FROM creature_loot_template WHERE entry BETWEEN 997000 AND 997199;
CREATE TABLE IF NOT EXISTS custom_mythic_boss (entry INT UNSIGNED NOT NULL PRIMARY KEY) ENGINE=InnoDB;
DELETE FROM custom_mythic_boss;

-- Textes des PNJ
UPDATE npc_text SET text0_0='Ce donjon peut être affronté dans une version bien plus redoutable.$B$BMode niveau 40 : ennemis niveau 40, boss niveau 41. Mode niveau 50 : ennemis niveau 50, boss niveau 51.$BMode mythique M0 à M+10 : ennemis niveau 60, plus nombreux et plus puissants ; réussir un niveau débloque le suivant.$B$BChoisissez avant d\'engager le combat : le mode est verrouillé dès le premier ennemi abattu.', text0_1='Ce donjon peut être affronté dans une version bien plus redoutable.$B$BMode niveau 40 : ennemis niveau 40, boss niveau 41. Mode niveau 50 : ennemis niveau 50, boss niveau 51.$BMode mythique M0 à M+10 : ennemis niveau 60, plus nombreux et plus puissants ; réussir un niveau débloque le suivant.$B$BChoisissez avant d\'engager le combat : le mode est verrouillé dès le premier ennemi abattu.' WHERE ID=990100;

