INSERT INTO npc_text (ID, text0_0, text0_1, prob0) VALUES (990101, 'Ce donjon peut être affronté en mode mythique.$B$BTous les ennemis passent au niveau 60, plus nombreux et plus puissants à chaque niveau, de M0 à M+10. Réussir un niveau (boss final vaincu) débloque le suivant. Les boss y laissent des objets mythiques.$B$BChoisissez avant d\'engager le combat : le mode est verrouillé dès le premier ennemi abattu.', 'Ce donjon peut être affronté en mode mythique.$B$BTous les ennemis passent au niveau 60, plus nombreux et plus puissants à chaque niveau, de M0 à M+10. Réussir un niveau (boss final vaincu) débloque le suivant. Les boss y laissent des objets mythiques.$B$BChoisissez avant d\'engager le combat : le mode est verrouillé dès le premier ennemi abattu.', 1);
